PAYLOAD = json.loads('{"src/cloud_soc/parsers/linux_operational.py": {"before": "8cd2866d51817ba5514659544e0378364045b9db68cc41e43b2f6e681561d059", "text": "\\"\\"\\"Selected Linux operational metadata; never return command arguments or bodies.\\"\\"\\"\\nimport json\\nimport re\\nfrom ipaddress import ip_address\\nfrom pathlib import PurePosixPath\\n\\nfrom cloud_soc.portal.log_contract import field\\nfrom cloud_soc.privacy import display, REDACTED\\n\\nVERSION = \\"linux-operational-v1\\"\\nPREFIX = re.compile(r\\"^(?P<time>[A-Z][a-z]{2}\\\\s+\\\\d{1,2}\\\\s+\\\\d{2}:\\\\d{2}:\\\\d{2})\\\\s+\\\\S+\\\\s+(?P<app>[A-Za-z0-9_.@-]+)(?:\\\\[(?P<pid>\\\\d{1,10})\\\\])?:\\\\s*(?P<body>.*)$\\")\\nSUDO = re.compile(r\\"^(?P<actor>[A-Za-z0-9_.@-]{1,128})\\\\s*:\\\\s*TTY=[^;\\\\n]{1,128}\\\\s*;\\\\s*PWD=[^;\\\\n]{1,1024}\\\\s*;\\\\s*USER=(?P<target>[A-Za-z0-9_.@-]{1,128})\\\\s*;\\\\s*(?:GROUP=[^;\\\\n]{1,128}\\\\s*;\\\\s*)?(?:TSID=[^;\\\\n]{1,128}\\\\s*;\\\\s*)?COMMAND=.+$\\")\\nSERVICE = re.compile(r\\"^(Starting|Started|Stopping|Stopped|Failed to start)\\\\s+.{1,1024}$\\")\\nACCESS = re.compile(r\'^(?P<ip>\\\\S{1,253})\\\\s+\\\\S+\\\\s+\\\\S+\\\\s+\\\\[(?P<time>\\\\d{2}/[A-Za-z]{3}/\\\\d{4}:\\\\d{2}:\\\\d{2}:\\\\d{2} [+-]\\\\d{4})\\\\]\\\\s+\\"(?P<method>GET|POST|PUT|DELETE|HEAD|OPTIONS|PATCH) [^\\"\\\\r\\\\n]{1,2048} HTTP/\\\\d(?:\\\\.\\\\d)?\\"\\\\s+(?P<status>[1-5]\\\\d{2})\\\\s+(?:\\\\d+|-)(?:(?:\\\\s+\\"[^\\"\\\\r\\\\n]{0,2048}\\"\\\\s+\\"[^\\"\\\\r\\\\n]{0,2048}\\")|(?P<extra>\\\\s+[A-Za-z0-9_.-]{1,128}\\\\s+[A-Za-z0-9_.-]{1,128}))?$\')\\nOBSERVED = {\\"gnome-shell\\": (\\"process\\", \\"desktop_log_observed\\"),\\n    \\"chrome\\": (\\"process\\", \\"desktop_log_observed\\"),\\n    \\"dbus-daemon\\": (\\"process\\", \\"message_bus_log_observed\\"),\\n    \\"chatgpt-desktop-linux_chatgpt-desktop-linux.desktop\\": (\\"process\\", \\"desktop_log_observed\\"),\\n    \\"google-chrome.desktop\\": (\\"process\\", \\"desktop_log_observed\\"),\\n    \\"NetworkManager\\": (\\"network\\", \\"network_service_log_observed\\"),\\n    \\"avahi-daemon\\": (\\"network\\", \\"network_service_log_observed\\"),\\n    \\"systemd-udevd\\": (\\"configuration\\", \\"device_service_log_observed\\"),\\n    \\"kernel\\": (\\"configuration\\", \\"kernel_log_observed\\")}\\n\\n\\ndef parse_linux_operational(source):\\n    if field(source, \\"labels.log_source\\") not in {\\"linux_file\\", \\"linux_journald\\", \\"linux_auth\\"}:\\n        return None\\n    message = source.get(\\"message\\")\\n    if not isinstance(message, str) or not message or len(message) > 8192 or \\"\\\\n\\" in message or \\"\\\\r\\" in message:\\n        return None\\n    path = field(source, \\"log.file.path\\")\\n    access = ACCESS.fullmatch(message) if isinstance(path, str) and PurePosixPath(path).name in {\\"access.log\\", \\"access_log\\"} else None\\n    if access:\\n        try:\\n            address = str(ip_address(access[\\"ip\\"]))\\n        except ValueError:\\n            # A hostname is not an IP address; omit it from source.ip.\\n            if not re.fullmatch(r\\"[A-Za-z0-9](?:[A-Za-z0-9.-]{0,251}[A-Za-z0-9])?\\", access[\\"ip\\"]):\\n                return None\\n            address = None\\n        limitations = [\\"url_headers_and_body_excluded\\", \\"not_a_detection\\"]\\n        if address is None:\\n            limitations.append(\\"client_hostname_not_stored\\")\\n        if access[\\"extra\\"]:\\n            limitations.append(\\"trailing_fields_uninterpreted\\")\\n        code = int(access[\\"status\\"])\\n        return {\\"adapter\\": \\"linux_operational_v1\\", \\"status\\": \\"partial\\" if address is None or access[\\"extra\\"] else \\"recognized\\",\\n                \\"access_time\\": access[\\"time\\"], \\"fields\\": {\\"category\\": \\"web\\", \\"action\\": \\"http_access\\",\\n                    \\"outcome\\": \\"failure\\" if code >= 400 else \\"success\\" if code < 300 else \\"unknown\\",\\n                    \\"source_ip\\": address, \\"http_method\\": access[\\"method\\"], \\"http_status\\": code},\\n                \\"missing\\": [\\"source_ip\\"] if address is None else [], \\"limitations\\": limitations}\\n    prefix = PREFIX.fullmatch(message)\\n    if prefix:\\n        app, body = prefix[\\"app\\"], prefix[\\"body\\"]\\n    elif field(source, \\"labels.log_source\\") == \\"linux_journald\\":\\n        app = (field(source, \\"log.syslog.appname\\") or field(source, \\"process.name\\")\\n               or field(source, \\"journald.syslog.identifier\\"))\\n        body = message\\n    else:\\n        app, body = None, message\\n    if app is None:\\n        # No actor/action inference. The collector timestamp is an observation time.\\n        if (field(source, \\"labels.log_source\\") != \\"linux_journald\\"\\n                and path not in {\\"/var/log/syslog\\", \\"/var/log/auth.log\\", \\"/var/log/kern.log\\"}):\\n            return None\\n        return {\\"adapter\\": \\"linux_unclassified_v1\\", \\"status\\": \\"partial\\",\\n                \\"fields\\": {\\"category\\": None, \\"action\\": \\"host_log_observed\\", \\"outcome\\": \\"unknown\\"},\\n                \\"missing\\": [\\"source_program\\", \\"source_event_time\\"],\\n                \\"limitations\\": [\\"metadata_only\\", \\"source_event_time_unknown\\", \\"message_body_excluded\\", \\"not_a_detection\\"]}\\n    values = {\\"category\\": \\"process\\", \\"outcome\\": \\"unknown\\"}\\n    if app == \\"sudo\\":\\n        match = SUDO.fullmatch(body)\\n        if not match:\\n            session = re.match(r\\"^pam_[A-Za-z0-9_]+\\\\(sudo:session\\\\): session (opened|closed)\\\\b\\", body)\\n            failure = re.match(r\\"^pam_[A-Za-z0-9_]+\\\\(sudo:auth\\\\): authentication failure(?:;|$)\\", body)\\n            if session:\\n                values.update(category=\\"authentication\\", action=\\"sudo_session_\\" + session[1])\\n            elif failure:\\n                values.update(category=\\"authentication\\", action=\\"sudo_authentication_failed\\", outcome=\\"failure\\")\\n            else:\\n                values.update(action=\\"sudo_log_observed\\", daemon=\\"sudo\\")\\n        else:\\n            actor, target = display(match[\\"actor\\"]), display(match[\\"target\\"])\\n            if actor in (None, REDACTED) or target in (None, REDACTED):\\n                return None\\n            values.update(action=\\"sudo_command_logged\\", actor=actor, target_user=target)\\n    elif app == \\"systemd\\":\\n        match = SERVICE.fullmatch(body)\\n        if not match:\\n            values.update(action=\\"systemd_log_observed\\", category=\\"configuration\\")\\n        else:\\n            actions = {\\"Starting\\": \\"service_start_requested\\", \\"Started\\": \\"service_started\\",\\n                       \\"Stopping\\": \\"service_stop_requested\\", \\"Stopped\\": \\"service_stopped\\",\\n                       \\"Failed to start\\": \\"service_start_failed\\"}\\n            values.update(action=actions[match[1]], category=\\"configuration\\",\\n                          outcome=\\"failure\\" if match[1] == \\"Failed to start\\" else \\"unknown\\")\\n    elif app in {\\"dockerd\\", \\"containerd\\"}:\\n        try:\\n            data = json.loads(body)\\n        except (ValueError, TypeError):\\n            match = re.fullmatch(r\'time=\\"[^\\"\\\\n]{1,64}\\"\\\\s+level=(debug|info|warning|warn|error|fatal)\\\\s+msg=\\"[^\\\\n]{0,4096}\\"(?:\\\\s+[^\\\\n]{0,2048})?\', body)\\n            if not match:\\n                if body.startswith((\\"time=\\", \\"{\\")):\\n                    return None\\n                data = {\\"level\\": \\"unknown\\"}\\n            else:\\n                data = {\\"level\\": match[1]}\\n        if not isinstance(data, dict) or data.get(\\"level\\") not in {\\"debug\\", \\"info\\", \\"warning\\", \\"warn\\", \\"error\\", \\"fatal\\", \\"unknown\\"}:\\n            return None\\n        values.update(action=\\"container_runtime_log_observed\\", daemon=app, log_level=data[\\"level\\"])\\n    elif app in OBSERVED:\\n        category, action = OBSERVED[app]\\n        values.update(category=category, action=action, daemon=app)\\n    else:\\n        return None\\n    result = {\\"adapter\\": \\"linux_operational_v1\\", \\"status\\": \\"recognized\\", \\"fields\\": values,\\n              \\"missing\\": [], \\"limitations\\": [\\"message_body_and_arguments_excluded\\", \\"not_a_detection\\"]}\\n    if prefix:\\n        result[\\"time_text\\"] = prefix[\\"time\\"]\\n    return result\\n"}, "tests/test_linux_operational.py": {"before": "f9b69af2a315da0127b46eebed57184b2be7391370862b9498532755b2bd1a00", "text": "\\"\\"\\"Privacy, source identity, outcome and immutable migration regression.\\"\\"\\"\\nimport copy\\nimport json\\nfrom pathlib import Path\\nimport sys\\nimport unittest\\n\\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / \\"src\\"))\\nfrom cloud_soc.parsers.linux_operational import parse_linux_operational\\nfrom cloud_soc.processing.contract import normalize\\n\\nNOW = \\"2026-10-05T04:00:00Z\\"\\n\\n\\ndef hit(message, app=\\"sudo\\", kind=\\"linux_journald\\"):\\n    return {\\"_index\\": \\"soc-host-raw-test\\", \\"_id\\": \\"synthetic\\", \\"_source\\": {\\n        \\"@timestamp\\": NOW, \\"event\\": {\\"ingested\\": NOW}, \\"organization\\": {\\"id\\": \\"fixture\\"},\\n        \\"labels\\": {\\"log_source\\": kind}, \\"process\\": {\\"name\\": app}, \\"message\\": message}}\\n\\n\\nclass LinuxOperationalTests(unittest.TestCase):\\n    def test_sudo_metadata_has_no_command_arguments_or_success_claim(self):\\n        sample = hit(\\"fixture : TTY=pts/0 ; PWD=/PRIVATE_CANARY ; USER=root ; COMMAND=/bin/sh -c \'password=PRIVATE_CANARY\'\\")\\n        original = copy.deepcopy(sample)\\n        key, record, event = normalize(sample, NOW)\\n        self.assertEqual(sample, original)\\n        self.assertEqual(record[\\"status\\"], \\"normalized\\")\\n        self.assertEqual(event[\\"event\\"][\\"outcome\\"], \\"unknown\\")\\n        self.assertEqual(event[\\"event\\"][\\"action\\"], \\"sudo_command_logged\\")\\n        self.assertEqual(event[\\"user\\"][\\"name\\"], \\"fixture\\")\\n        self.assertEqual(event[\\"cloud_soc\\"][\\"detail\\"][\\"fields\\"][\\"target_user\\"], \\"root\\")\\n        self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps([record, event]))\\n        self.assertEqual(event[\\"cloud_soc\\"][\\"normalizer_version\\"], \\"linux-operational-v1\\")\\n        old = hit(\\"unsupported\\", \\"unrelated\\")\\n        self.assertNotEqual(key, normalize(old, NOW)[0])\\n        self.assertEqual(key, normalize(sample, \\"2026-10-05T05:00:00Z\\")[0])\\n\\n    def test_file_prefix_requires_timezone_and_preserves_source_timestamp(self):\\n        sample = hit(\\"Oct  5 04:00:00 fixture sudo[12]: fixture : TTY=pts/0 ; PWD=/ ; USER=root ; COMMAND=/bin/true\\", kind=\\"linux_file\\")\\n        self.assertEqual(normalize(sample, NOW)[1][\\"reason\\"], \\"linux_timezone_missing\\")\\n        sample[\\"_source\\"][\\"event\\"][\\"timezone\\"] = \\"UTC\\"\\n        event = normalize(sample, NOW)[2]\\n        self.assertEqual(event[\\"@timestamp\\"], NOW)\\n        sample[\\"_source\\"][\\"event\\"][\\"timezone\\"] = \\"invalid\\"\\n        self.assertEqual(normalize(sample, NOW)[1][\\"reason\\"], \\"linux_time_invalid\\")\\n\\n    def test_systemd_failure_and_lifecycle_do_not_retain_description(self):\\n        for message, action, outcome in (\\n            (\\"Failed to start PRIVATE_CANARY.\\", \\"service_start_failed\\", \\"failure\\"),\\n            (\\"Started PRIVATE_CANARY.\\", \\"service_started\\", \\"unknown\\"),\\n            (\\"Starting PRIVATE_CANARY...\\", \\"service_start_requested\\", \\"unknown\\"),\\n        ):\\n            event = normalize(hit(message, \\"systemd\\"), NOW)[2]\\n            self.assertEqual(event[\\"event\\"][\\"action\\"], action)\\n            self.assertEqual(event[\\"event\\"][\\"outcome\\"], outcome)\\n            self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps(event))\\n\\n    def test_docker_json_and_logfmt_extract_only_level(self):\\n        for message in (\'{\\"level\\":\\"error\\",\\"msg\\":\\"password=PRIVATE_CANARY\\"}\',\\n                        \'time=\\"2026-10-05T04:00:00Z\\" level=info msg=\\"PRIVATE_CANARY\\" module=runtime\'):\\n            event = normalize(hit(message, \\"dockerd\\"), NOW)[2]\\n            self.assertEqual(event[\\"event\\"][\\"outcome\\"], \\"unknown\\")\\n            self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps(event))\\n\\n    def test_unknown_malformed_and_wrong_provider_are_not_supported(self):\\n        for sample in (hit(\\"Started example.\\", \\"unrelated\\"),\\n                       hit(\'time=\\"x\\" level=unknown msg=\\"x\\"\', \\"dockerd\\"),\\n                       hit(\\"Started x.\\\\nforged\\", \\"systemd\\"), hit(\\"x\\" * 8193)):\\n            self.assertIsNone(parse_linux_operational(sample[\\"_source\\"]))\\n        sample = hit(\\"Started example.\\", \\"systemd\\")\\n        sample[\\"_index\\"] = \\"soc-cloud-aws-test\\"\\n        self.assertEqual(normalize(sample, NOW)[1][\\"reason\\"], \\"source_scope_mismatch\\")\\n\\n    def test_desktop_kernel_and_network_metadata_are_not_authentication(self):\\n        for app in (\\"gnome-shell\\", \\"kernel\\", \\"NetworkManager\\", \\"avahi-daemon\\", \\"systemd-udevd\\"):\\n            event = normalize(hit(\\"PRIVATE_CANARY arbitrary message\\", app), NOW)[2]\\n            self.assertNotIn(\\"authentication\\", event[\\"event\\"][\\"category\\"])\\n            self.assertEqual(event[\\"event\\"][\\"outcome\\"], \\"unknown\\")\\n            self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps(event))\\n\\n    def test_pam_sudo_session_and_auth_failure(self):\\n        for body, action, outcome in (\\n            (\\"pam_unix(sudo:session): session opened for user root by fixture\\", \\"sudo_session_opened\\", \\"unknown\\"),\\n            (\\"pam_unix(sudo:session): session closed for user root\\", \\"sudo_session_closed\\", \\"unknown\\"),\\n            (\\"pam_unix(sudo:auth): authentication failure; logname=PRIVATE_CANARY\\", \\"sudo_authentication_failed\\", \\"failure\\"),\\n        ):\\n            event = normalize(hit(body), NOW)[2]\\n            self.assertEqual(event[\\"event\\"][\\"action\\"], action)\\n            self.assertEqual(event[\\"event\\"][\\"outcome\\"], outcome)\\n            self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps(event))\\n\\n    def test_access_log_explicit_offset_and_no_url_or_headers(self):\\n        sample = hit(\'192.0.2.1 - - [05/Oct/2026:13:00:00 +0900] \\"GET /?token=PRIVATE_CANARY HTTP/1.1\\" 401 12 \\"PRIVATE_CANARY\\" \\"PRIVATE_CANARY\\"\', kind=\\"linux_file\\")\\n        sample[\\"_source\\"][\\"log\\"] = {\\"file\\": {\\"path\\": \\"/var/log/nginx/access_log\\"}}\\n        event = normalize(sample, NOW)[2]\\n        self.assertEqual(event[\\"@timestamp\\"], NOW)\\n        self.assertEqual(event[\\"event\\"][\\"category\\"], [\\"web\\"])\\n        self.assertEqual(event[\\"event\\"][\\"outcome\\"], \\"failure\\")\\n        self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps(event))\\n        sample[\\"_source\\"][\\"message\\"] = sample[\\"_source\\"][\\"message\\"].replace(\\"05/Oct\\", \\"32/Oct\\")\\n        self.assertEqual(normalize(sample, NOW)[1][\\"reason\\"], \\"linux_time_invalid\\")\\n\\n    def test_remaining_known_providers_are_observed_without_semantic_guessing(self):\\n        for app in (\\"sudo\\", \\"dbus-daemon\\", \\"chrome\\"):\\n            event = normalize(hit(\\"PRIVATE_CANARY unknown payload\\", app), NOW)[2]\\n            self.assertEqual(event[\\"event\\"][\\"outcome\\"], \\"unknown\\")\\n            self.assertNotIn(\\"authentication\\", event[\\"event\\"][\\"category\\"])\\n            self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps(event))\\n\\n    def test_unidentified_messages_are_partial_metadata_not_authentication(self):\\n        sample = hit(\\"PRIVATE_CANARY unidentified payload\\")\\n        del sample[\\"_source\\"][\\"process\\"]\\n        key, record, event = normalize(sample, NOW)\\n        self.assertEqual(record[\\"adapter\\"], \\"linux_unclassified_v1\\")\\n        self.assertEqual(event[\\"event\\"][\\"category\\"], [])\\n        self.assertEqual(event[\\"event\\"][\\"outcome\\"], \\"unknown\\")\\n        self.assertEqual(event[\\"cloud_soc\\"][\\"parse_status\\"], \\"partial\\")\\n        self.assertFalse(event[\\"cloud_soc\\"][\\"provenance\\"][\\"time\\"][\\"source_event_time_known\\"])\\n        self.assertNotIn(\\"PRIVATE_CANARY\\", json.dumps([record, event]))\\n        sample[\\"_source\\"][\\"labels\\"][\\"log_source\\"] = \\"linux_file\\"\\n        self.assertIsNone(normalize(sample, NOW)[2])\\n        sample[\\"_source\\"][\\"log\\"] = {\\"file\\": {\\"path\\": \\"/var/log/syslog\\"}}\\n        self.assertEqual(normalize(sample, NOW)[1][\\"adapter\\"], \\"linux_unclassified_v1\\")\\n\\n    def test_hostname_access_with_two_uninterpreted_fields(self):\\n        sample = hit(\'localhost - - [05/Oct/2026:13:00:00 +0900] \\"POST /PRIVATE_CANARY HTTP/1.1\\" 200 12 Print-Job successful-ok\', kind=\\"linux_file\\")\\n        sample[\\"_source\\"][\\"log\\"] = {\\"file\\": {\\"path\\": \\"/var/log/cups/access_log\\"}}\\n        event = normalize(sample, NOW)[2]\\n        self.assertEqual(event[\\"cloud_soc\\"][\\"parse_status\\"], \\"partial\\")\\n        self.assertEqual(event[\\"event\\"][\\"category\\"], [\\"web\\"])\\n        self.assertNotIn(\\"source\\", event)\\n        for value in (\\"PRIVATE_CANARY\\", \\"localhost\\", \\"Print-Job\\", \\"successful-ok\\"):\\n            self.assertNotIn(value, json.dumps(event))\\n        self.assertIn(\\"trailing_fields_uninterpreted\\", event[\\"cloud_soc\\"][\\"detail\\"][\\"limitations\\"])\\n        sample[\\"_source\\"][\\"message\\"] += \\" unexpected-third-field\\"\\n        self.assertIsNone(normalize(sample, NOW)[2])\\n"}}')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", required=True)
    args = parser.parse_args()
    repo = Path(args.repo).resolve()
    if not (repo / ".git").exists():
        raise SystemExit("Not a git checkout")
    changes = []
    for name, item in PAYLOAD.items():
        target = repo / name
        if target.is_symlink() or repo not in target.resolve().parents:
            raise SystemExit("Unsafe source path: " + name)
        current = hashlib.sha256(target.read_bytes()).hexdigest() if target.exists() else None
        wanted = hashlib.sha256(item["text"].encode()).hexdigest()
        if current == wanted:
            continue
        if current != item["before"]:
            raise SystemExit("Source differs; no files changed: " + name)
        changes.append((name, item, target))
    if not changes:
        print("Already applied")
        return
    backup = repo / "state/deploy-backups" / datetime.now(timezone.utc).strftime("linux-parser-source-%Y%m%d-%H%M%S-%f")
    os.umask(0o077)
    backup.mkdir(parents=True, mode=0o700)
    for name, item, target in changes:
        if target.exists():
            dest = backup / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, dest)
    for name, item, target in changes:
        attrs = target.stat() if target.exists() else target.parent.stat()
        descriptor, temporary = tempfile.mkstemp(dir=target.parent, prefix=".linux-parser-")
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as output:
                output.write(item["text"])
            os.chmod(temporary, target.stat().st_mode & 0o777 if target.exists() else 0o644)
            if os.geteuid() == 0:
                os.chown(temporary, attrs.st_uid, attrs.st_gid)
            os.replace(temporary, target)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
        print("Updated:", name)
    print("Source backup:", backup)
    print("No services restarted; no state files or collected documents changed")


if __name__ == "__main__":
    main()
